import random
random.seed(7)
draws = [sorted(random.sample(range(1, 91), 6)) for _ in range(300)]
last = {}
for i, d in enumerate(draws):
    for n in d:
        last[n] = i
gaps = {n: 300 - 1 - last.get(n, -1) for n in range(1, 91)}
print("SIMULATED set: 300 draws, fixed seed 7 (not real history)")
print("average gap between appearances (draws):", 90 // 6)
print("longest gaps since last appearance:", sorted(gaps.items(), key=lambda kv: kv[1])[-5:])
print("a long gap does not raise the next-draw chance: still 6 in 90")
